import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Inline CUDA extension
# ----------------------------------------------------------------------
src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int THREADS>
__global__ void cross_entropy_fp16_kernel(
    const __half* __restrict__ logits,
    const int64_t* __restrict__ targets,
    float* __restrict__ loss_sum,
    const int batch_size,
    const int num_classes)
{
    // One block per sample
    const int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    // Pointer to the start of this sample's logits
    const __half* sample_logits = logits + batch_idx * num_classes;
    const int target = static_cast<int>(targets[batch_idx]);

    // ------------------------------------------------------------------
    // 1) Compute max logit for numerical stability
    // ------------------------------------------------------------------
    __shared__ float s_max;
    float thread_max = -FLT_MAX;
    for (int i = threadIdx.x; i < num_classes; i += THREADS) {
        float val = __half2float(sample_logits[i]);
        if (val > thread_max) thread_max = val;
    }
    // Reduce within block
    static __shared__ float sdata[THREADS];
    sdata[threadIdx.x] = thread_max;
    __syncthreads();

    // Parallel reduction (warp-unrolled)
    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            float other = sdata[threadIdx.x + offset];
            if (other > sdata[threadIdx.x]) sdata[threadIdx.x] = other;
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) s_max = sdata[0];
    __syncthreads();

    // ------------------------------------------------------------------
    // 2) Compute sum of exp(logit - max)
    // ------------------------------------------------------------------
    float thread_sum = 0.0f;
    for (int i = threadIdx.x; i < num_classes; i += THREADS) {
        float val = __half2float(sample_logits[i]);
        thread_sum += expf(val - s_max);
    }

    // Reduce sum within block
    sdata[threadIdx.x] = thread_sum;
    __syncthreads();
    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            sdata[threadIdx.x] += sdata[threadIdx.x + offset];
        }
        __syncthreads();
    }
    float sum_exp = sdata[0];
    __syncthreads();

    // ------------------------------------------------------------------
    // 3) Compute loss for this sample: - (logit_target - log_sum_exp)
    // ------------------------------------------------------------------
    float logit_target = __half2float(sample_logits[target]);
    float log_sum_exp = s_max + logf(sum_exp);
    float loss_i = -(logit_target - log_sum_exp);

    // ------------------------------------------------------------------
    // 4) Accumulate into global loss sum (float for precision)
    // ------------------------------------------------------------------
    atomicAdd(loss_sum, loss_i);
}

// Wrapper
torch::Tensor cross_entropy_fp16(torch::Tensor logits, torch::Tensor targets) {
    TORCH_CHECK(logits.is_cuda() && targets.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(logits.dtype() == torch::kHalf, "logits must be float16");
    TORCH_CHECK(targets.dtype() == torch::kLong, "targets must be int64");
    TORCH_CHECK(logits.dim() == 2, "logits must be 2D (batch, classes)");

    const int batch_size = logits.size(0);
    const int num_classes = logits.size(1);

    // Output scalar loss (float16)
    auto loss = torch::empty({1}, logits.options());

    // Allocate temporary float accumulator
    float* d_loss_sum;
    cudaMalloc(&d_loss_sum, sizeof(float));
    cudaMemset(d_loss_sum, 0, sizeof(float));

    // Launch configuration
    constexpr int THREADS = 256;
    dim3 blocks(batch_size);
    dim3 threads(THREADS);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(logits.scalar_type(), "cross_entropy_fp16_kernel", ([&] {
        cross_entropy_fp16_kernel<THREADS><<<blocks, threads>>>(
            logits.data_ptr<__half>(),
            targets.data_ptr<int64_t>(),
            d_loss_sum,
            batch_size,
            num_classes);
    }));

    // Copy back and average
    float h_sum;
    cudaMemcpy(&h_sum, d_loss_sum, sizeof(float), cudaMemcpyDeviceToHost);
    h_sum /= static_cast<float>(batch_size);
    // Cast to half and store in output tensor
    loss[0] = __float2half(h_sum);

    cudaFree(d_loss_sum);
    return loss;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cross_entropy_fp16", &cross_entropy_fp16, "Cross Entropy FP16 (CUDA)");
}
'''

# Compile the inline extension
module = load_inline(name='cross_entropy_fp16_ext',
                     cpp_sources='',
                     cuda_sources=src,
                     functions=['cross_entropy_fp16'],
                     verbose=False)

# ----------------------------------------------------------------------
# ModelNew definition using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for torch.nn.functional.cross_entropy using a custom
    CUDA kernel that operates on fp16 tensors.
    """
    def __init__(self):
        super().__init__()

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor):
        # Ensure predictions are half precision and contiguous
        preds = predictions.to(dtype=torch.float16).contiguous()
        tgs = targets.contiguous()
        return module.cross_entropy_fp16(preds, tgs)

# ----------------------------------------------------------------------
# Helper functions matching the reference interface
# ----------------------------------------------------------------------
def get_inputs():
    batch_size = 32768
    num_classes = 4096
    preds = torch.rand(batch_size, num_classes, dtype=torch.float16, device='cuda')
    tgts = torch.randint(0, num_classes, (batch_size,), dtype=torch.long, device='cuda')
    return [preds, tgts]

def get_init_inputs():
    return []

# Example sanity check (can be removed in production)
if __name__ == "__main__":
    model_ref = nn.Module()
    model_ref.forward = lambda p, t: F.cross_entropy(p, t)
    model_new = ModelNew()
    preds, tgts = get_inputs()
    loss_ref = model_ref.forward(preds, tgts)
    loss_new = model_new.forward(preds, tgts)
    print(f"Ref loss: {loss_ref.item():.6f}, New loss: {loss_new.item():.6f}")
